import 'package:drift/drift.dart'; import '../app_database.dart';
@DriftAccessor()
class SyncDao extends DatabaseAccessor<AppDatabase> { SyncDao(AppDatabase db):super(db); Future<List<SyncOperation>> _by(String s)=>(db.select(db.syncOperations)..where((t)=>t.status.equals(s))..orderBy([(t)=>OrderingTerm.asc(t.createdAt)])).get(); Future<List<SyncOperation>> getPendingOperations()=>_by('pending'); Future<List<SyncOperation>> getFailedOperations()=>_by('failed'); Future<List<SyncOperation>> getConflictingOperations()=>_by('conflict'); Future<void> appendOperation(SyncOperationsCompanion v)=>db.into(db.syncOperations).insert(v); Future<int> updateOperationStatus(String id,String status,{String? errorMessage})=>(db.update(db.syncOperations)..where((t)=>t.id.equals(id))).write(SyncOperationsCompanion(status:Value(status),errorMessage:Value(errorMessage))); Future<int> incrementRetryCount(String id,DateTime at)=>(db.customUpdate('UPDATE sync_operations SET retry_count=retry_count+1,last_attempt_at=? WHERE id=?',variables:[Variable(at.toUtc()),Variable(id)],updates:{db.syncOperations})); }
